import{_ as a,o as n,c as l,am as e}from"./chunks/framework.CiF4W93w.js";const h=JSON.parse('{"title":"面试煎熬成蛋_框架","description":"","frontmatter":{"title":"面试煎熬成蛋_框架","excerpt":"面试煎熬成蛋_框架","date":"2024-03-09 19:11:53","updated":"2024-02-29 00:01:18"},"headers":[],"relativePath":"Java面试准备/面试煎熬成蛋_框架/index.md","filePath":"Java面试准备/面试煎熬成蛋_框架/index.md","lastUpdated":null}'),p={name:"Java面试准备/面试煎熬成蛋_框架/index.md"};function o(s,i,t,r,c,u){return n(),l("div",null,[...i[0]||(i[0]=[e(`<h3 id="spring" tabindex="-1">Spring <a class="header-anchor" href="#spring" aria-label="Permalink to &quot;Spring&quot;">​</a></h3><h4 id="bean线程安全" tabindex="-1">Bean线程安全 <a class="header-anchor" href="#bean线程安全" aria-label="Permalink to &quot;Bean线程安全&quot;">​</a></h4><blockquote><p>Spring 框架中的单例 Bean 是线程安全的吗</p></blockquote><p>并不是线程安全的，Spring框架中的单例Bean本身对于线程安全性并没有提供保证。</p><p>单例Bean意味着在Spring的应用上下文中，每个定义的Bean只有一个实例。但是，Bean的线程安全性取决于Bean的实现和使用方式。</p><ul><li><strong>状态无关的Bean</strong>：如果Bean是无状态的（即，它们不维护任何字段或状态信息），那么它们通常是线程安全的。例如，一个只有方法，没有成员变量的服务类，或者成员变量都是不可变的或线程安全的。</li><li><strong>状态相关的Bean</strong>：如果Bean包含有状态（即，它们维护了修改的字段或状态信息），那么它们可能不是线程安全的。在并发访问下，如果多个线程同时修改这些状态，可能会导致数据不一致或其他并发问题。</li></ul><p>服务器中的代码片段</p><p>Spring Bean 并没有可变的状态（比如 Service 类和 Dao 类），所以在某种程度上说 Spring 的单例 bean 是线程安全的。</p><p>但如果 Bean 中包含了修改的字段或者状态信息, 多线程环境下会存在线程安全问题。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@Component</span></span>
<span class="line"><span>public class CounterBean {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    private int count = 0;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    public void increment() {</span></span>
<span class="line"><span>        count++;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    public int getCount() {</span></span>
<span class="line"><span>        return count;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>以上的<code>CounterBean</code>就是一个有状态的Bean，多线程环境下对<code>increment</code>方法的调用就会导致线程安全问题。</p><p>面试题回答</p><blockquote><p>Spring 框架中的单例 Bean 是线程安全的吗</p></blockquote><ul><li>不是线程安全的</li><li>Spring 的 Bean 默认是单例的，是否是线程安全有两种情况 <ul><li>在spring的bean的中都是注入无状态的对象，没有线程安全问题</li><li>如果在bean中定义了可修改的成员变量，是要考线程安全问题的 <ul><li>可以使用多例或者加锁来解决</li></ul></li></ul></li></ul><hr><h4 id="aop" tabindex="-1">AOP <a class="header-anchor" href="#aop" aria-label="Permalink to &quot;AOP&quot;">​</a></h4><blockquote><p>什么是 AOP，你们项目中有没有使用到 AOP</p></blockquote><p>回答这道题目，一般建议围绕首先自己对于 AOP的理解概念，然后结合实际场景题，包括自己项目中是如何使用到 AOP ，然后讲述自己对于它的理解。</p><p>AOP称为面向切面编程，用于将那些与业务无关，但却对多个对象产生影响的公共行为和逻辑，抽取并封装为一个 可重用的模块，这个模块被命名为“切面”(Aspect),减少系统中的重复代码，降低了模块间的调合度，同时提高了系统的可维护性，</p><p>常见的AOP 使用场景是：</p><ul><li>记录操作日志</li><li>缓存处理</li><li>Spring中内置的事务处理</li></ul><h5 id="日志记录" tabindex="-1">日志记录 <a class="header-anchor" href="#日志记录" aria-label="Permalink to &quot;日志记录&quot;">​</a></h5><p>记录操作日志思路</p><ul><li>获取请求的用户名、请求方式、访问地址、模块名称、登陆IP、操作时间，记录到数据库的日志表中。</li></ul><p>日志的实际记入方式可用说一下，然后日志在项目中是如何用到的（建议说一下蘑菇博客上面记录日志的方式）</p><h5 id="事务实现" tabindex="-1">事务实现 <a class="header-anchor" href="#事务实现" aria-label="Permalink to &quot;事务实现&quot;">​</a></h5><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240229001802.png" alt="image.png"></p><p>感觉AOP 这里的回答建议还是要和反向代理一起说一下，具体实现方式当然也可用说，到时候随机应变了。</p><blockquote><p>面试题回答</p></blockquote><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240229001857.png" alt="image.png"></p><h4 id="事务失效" tabindex="-1">事务失效 <a class="header-anchor" href="#事务失效" aria-label="Permalink to &quot;事务失效&quot;">​</a></h4><p>事务管理通过声明式事务和编程式事务来提供对事务的支持。在某些场景下，Spring事务可能会失效，导致事务不按预期执行。</p><p>这些场景主要包括：</p><ul><li><ol><li>方法非公开（Non-public Method）</li></ol><ul><li>Spring的声明式事务管理是通过动态代理实现的。</li><li>如果一个类中被<code>@Transactional</code>标注的方法不是public的，那么Spring AOP将无法创建有效的代理对象，导致事务管理不生效。</li></ul></li><li><ol start="2"><li>自调用（Self-invocation）</li></ol><ul><li>当在同一个类中的一个方法直接调用另一个带有<code>@Transactional</code>注解的方法时，事务是不会被触发的。</li><li>这是因为动态代理的限制，事务的应用需要通过代理对象来调用目标方法。自调用场景绕过了代理对象，直接在目标对象内部调用，因此事务不生效。</li></ul></li><li><ol start="3"><li>异常处理不当</li></ol><ul><li>Spring事务默认只对<code>RuntimeException</code>（运行时异常）和<code>Error</code>进行回滚，对于检查型异常（<code>Exception</code>的其他子类）不会回滚。</li><li>如果需要对检查型异常进行回滚，需要在<code>@Transactional</code>注解的<code>rollbackFor</code>属性中显式声明。</li></ul></li><li><ol start="4"><li>数据源未配置事务管理器</li></ol></li><li><ol start="5"><li>错误的事务传播行为配置</li></ol></li><li><ol start="6"><li>事务方法被内联编译优化</li></ol></li><li><ol start="7"><li>不恰当的隔离级别或超时设置</li></ol></li></ul><p>建议回答一下前三点。</p><blockquote><p>视频讲解部分内容：</p></blockquote><p>异常捕获处理</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240229002244.png" alt="image.png"></p><p>抛出检查异常 <img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240229002325.png" alt="image.png"> 非 public 方法导致的事务失效</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240229002350.png" alt="image.png"></p><blockquote><p>面试题</p></blockquote><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240229002419.png" alt="image.png"></p><h4 id="bean的生命周期-🚩" tabindex="-1">Bean的生命周期 🚩 <a class="header-anchor" href="#bean的生命周期-🚩" aria-label="Permalink to &quot;Bean的生命周期  🚩&quot;">​</a></h4><blockquote><p>Spring 容器是如何管理和创建 bean 实例</p></blockquote><blockquote><p>方便调试和解决问题</p></blockquote><p>Bean 的流程 → 代码验证</p><p>BeanDefinition</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240229081346.png" alt="image.png"></p><p>生命周期</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240229081603.png" alt="image.png"></p><p>可以参考一下这个: <a href="https://www.bilibili.com/video/BV1yT411H7YK/?p=39&amp;spm_id_from=pageDriver&amp;vd_source=6a019ecccfe7d8f62b9a3fe99c723bd0" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1yT411H7YK/?p=39&amp;spm_id_from=pageDriver&amp;vd_source=6a019ecccfe7d8f62b9a3fe99c723bd0</a></p><p>自定义了一个类，然后看 Bean 在 Spring 中的一个执行流程（看输出的一个顺序）</p><blockquote><p>面试题回答</p></blockquote><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240229082037.png" alt="image.png"></p><h4 id="循环依赖-🚩" tabindex="-1">循环依赖 🚩 <a class="header-anchor" href="#循环依赖-🚩" aria-label="Permalink to &quot;循环依赖   🚩&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240315154746.png" alt="image.png"></p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240315153729.png" alt="image.png"></p><p>看一下相关的解析：</p><p>关于三级缓存解决循环引用的描述，基本思路是对的，但描述过程中的一些细节需要更准确地表达：</p><ol><li><strong>开始实例化对象A</strong>：当Spring容器开始创建Bean A时，如果发现A依赖于B，它会暂停A的创建过程，并开始创建B。</li><li><strong>放入三级缓存</strong>：在这个过程中，Spring容器实际上会将创建A的部分完成的实例（也就是说，这个实例已经分配了内存，但它的依赖还没有完全解决）的工厂放入三级缓存中。这个工厂负责生成A的引用，以便在需要时可以提前暴露出来。</li><li><strong>创建对象B</strong>：在创建B的过程中，如果B需要依赖于A，Spring容器会尝试从缓存中获取A的实例。此时，它会从三级缓存中获取A的工厂，使用这个工厂创建A的早期引用，并将这个引用提升到二级缓存中。</li><li><strong>完成对象B的创建</strong>：有了A的引用后，Spring容器可以继续B的创建过程，并解决其对A的依赖。</li><li><strong>完成对象A的创建</strong>：一旦B被成功创建并设置到A中，Spring容器回到A的创建过程中，完成A的创建并解决其他可能的依赖。</li></ol><p>通过三级缓存机制，Spring能够处理循环依赖的情况，允许A和B互相引用而不导致死锁或Bean创建失败。</p><p>不过，需要注意的是，Spring的这种三级缓存机制只能解决单例作用域Bean的循环依赖问题，并且主要解决的是Setter注入或字段注入造成的循环依赖。对于构造器注入导致的循环依赖，Spring是无法解决的。</p><p>👇</p><p>构造方法出现了循环依赖的话，可以使用 @Lazy 进行懒加载</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240315153845.png" alt="image.png"></p><h4 id="常用注解" tabindex="-1">常用注解 <a class="header-anchor" href="#常用注解" aria-label="Permalink to &quot;常用注解&quot;">​</a></h4><p>Spring框架常见注解(Spring、Springboot、Springmvc)</p><h5 id="spring-1" tabindex="-1">Spring <a class="header-anchor" href="#spring-1" aria-label="Permalink to &quot;Spring&quot;">​</a></h5><ul><li>@Componetn、@Controller、@Service、@Repository</li><li>@Autowired</li><li>@Qualifier</li><li>@Scope</li><li>@Configuration</li><li>@ComponentScan</li><li>@Bean</li><li>@Import</li><li>@Aspect、@Before、@After、@Around、@Pointcut</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402290951343.png" alt="image.png"></p><h5 id="springmvc" tabindex="-1">SpringMVC <a class="header-anchor" href="#springmvc" aria-label="Permalink to &quot;SpringMVC&quot;">​</a></h5><ul><li>@RequestMapping</li><li>@RequestBody</li><li>@RequestParam</li><li>@PathViriable</li><li>@ResponseBody</li><li>@RequestHeader</li><li>@RestController</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402290956678.png" alt="image.png"></p><h5 id="springboot" tabindex="-1">SpringBoot <a class="header-anchor" href="#springboot" aria-label="Permalink to &quot;SpringBoot&quot;">​</a></h5><ul><li>@SpringBootConfiguration</li><li>@EnableAutoConfiguration</li><li>@CompnentScan</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402290957400.png" alt="image.png"></p><h4 id="你们项目中有用过-spi-吗-是否自己封装过组件-🚩" tabindex="-1">你们项目中有用过 SPI 吗，是否自己封装过组件 🚩 <a class="header-anchor" href="#你们项目中有用过-spi-吗-是否自己封装过组件-🚩" aria-label="Permalink to &quot;你们项目中有用过 SPI 吗，是否自己封装过组件  🚩&quot;">​</a></h4><h4 id="有没有自定义过-beanpost-xxx-具体怎么使用的-🚩" tabindex="-1">有没有自定义过 BeanPost xxx ，具体怎么使用的 🚩 <a class="header-anchor" href="#有没有自定义过-beanpost-xxx-具体怎么使用的-🚩" aria-label="Permalink to &quot;有没有自定义过 BeanPost xxx ，具体怎么使用的  🚩&quot;">​</a></h4><h3 id="springmvc-1" tabindex="-1">SpringMVC <a class="header-anchor" href="#springmvc-1" aria-label="Permalink to &quot;SpringMVC&quot;">​</a></h3><h4 id="执行流程" tabindex="-1">执行流程 <a class="header-anchor" href="#执行流程" aria-label="Permalink to &quot;执行流程&quot;">​</a></h4><p>Springmvc的执行流程是这个框架最核心的内容</p><ul><li>1、视图阶段（老旧JSP等 ）</li><li>2、前后端分离阶段（接口开发，异步）</li></ul><blockquote><p>视图阶段</p></blockquote><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402290943468.png" alt="image.png"></p><blockquote><p>前后端分离</p></blockquote><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402290944546.png" alt="image.png"></p><p>面试题：</p><ul><li>1、浏览器发起请求，前端控制器进行处理（调用处理器映射器）；</li><li>2、前端控制器通过处理器映射器会找到具体的处理器 Handler，生成处理器对象以及处理器拦截器（如果有），一起返回给 DispatcherServlet。</li><li>3、前端控制器调用处理器适配器，适配器调用对应的 处理器 进行处理用户请求</li><li>4、处理完成后返回 ModelAndView 对象，经过视图解析器处理返回视图，进行渲染后填充前端，进行响应</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402290945750.png" alt="image.png"></p><p>版本2：</p><ul><li>1、浏览器发起请求，前端控制器进行处理（调用处理器映射器）；</li><li>2、前端控制器通过处理器映射器会找到具体的处理器 Handler，生成处理器对象以及处理器拦截器（如果有），一起返回给 DispatcherServlet。</li><li>3、前端控制器调用处理器适配器，适配器调用对应的 处理器 进行处理用户请求</li><li>4、一般此时 Controller 方法上会添加 @ResponseBody 注解，会进行将返回结构转换为 Json 并响应前端</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402290946621.png" alt="image.png"></p><h3 id="springboot-1" tabindex="-1">SpringBoot <a class="header-anchor" href="#springboot-1" aria-label="Permalink to &quot;SpringBoot&quot;">​</a></h3><h4 id="自动配置原理-🚩" tabindex="-1">自动配置原理 🚩 <a class="header-anchor" href="#自动配置原理-🚩" aria-label="Permalink to &quot;自动配置原理  🚩&quot;">​</a></h4><p>这道题目待复习一下</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402290947817.png" alt="image.png"></p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402290948762.png" alt="image.png"></p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402290949754.png" alt="image.png"></p><p>2,其中@EnableAutoConfiguration是实现自动化配置的核心注解。</p><ul><li>该注解通过@Importi注解导入对应的配置选择器。</li><li>内部就是读取了该项目和该项目引用的ar包的的classpath路径下META-NF/spring.factories文件中的所配置的类的全类名。</li><li>在这些配置类中所定义的Bean会根据条件注解所指定的条件来决定是否需要将其导入到Spring容器中。</li><li>3,条件判断会有像 @ConditionalOnClassi这样的注解，判断是否有对应的class文件，如果有则加载该类，把这个配置类的所有的 Bean放入 spring容器中使用.</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402290950693.png" alt="image.png"></p><h3 id="mybatis" tabindex="-1">Mybatis <a class="header-anchor" href="#mybatis" aria-label="Permalink to &quot;Mybatis&quot;">​</a></h3><h4 id="和-替换" tabindex="-1"># 和 { } 替换 <a class="header-anchor" href="#和-替换" aria-label="Permalink to &quot;# 和 { } 替换&quot;">​</a></h4><h4 id="动态标签" tabindex="-1">动态标签 <a class="header-anchor" href="#动态标签" aria-label="Permalink to &quot;动态标签&quot;">​</a></h4><p>if、where、set</p><p>select、foreach，</p><h4 id="执行流程-🚩" tabindex="-1">执行流程 🚩 <a class="header-anchor" href="#执行流程-🚩" aria-label="Permalink to &quot;执行流程  🚩&quot;">​</a></h4><hr><p>Mybatis 执行流程</p><ul><li>1、理解各个组件的关系</li><li>2、Sql 的执行过程（参数映射、sql 解析、执行和结果处理）</li></ul><blockquote><p>讲一下 mybatis 的配置文件的 xml 文件的作用有哪些？</p></blockquote><ul><li>加载核心配置</li><li>加载映射文件</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402291030799.png" alt="image.png"></p><p>执行流程</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402291131905.png" alt="image.png"></p><p>面试题</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402291132269.png" alt="image.png"></p><h4 id="延迟加载-🚩" tabindex="-1">延迟加载 🚩 <a class="header-anchor" href="#延迟加载-🚩" aria-label="Permalink to &quot;延迟加载   🚩&quot;">​</a></h4><p>延迟加载操作：需要配置文件中开启（关联对象集合的延迟加载）</p><p>实现原理：动态代理，CGLIB</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402291133046.png" alt="image.png"></p><ul><li>1、设置局部的延迟加载</li><li>2、设置全部的延迟加载</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402291137882.png" alt="image.png"></p><p>主要看一下这个：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402291138401.png" alt="image.png"></p><h4 id="一二级缓存-🚩" tabindex="-1">一二级缓存 🚩 <a class="header-anchor" href="#一二级缓存-🚩" aria-label="Permalink to &quot;一二级缓存  🚩&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402291142061.png" alt="image.png"> 二级缓存</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402291144414.png" alt="image.png"></p><p>注意事项：</p><ul><li>1、对于缓存数据更新机制，当某一个作用域（一级缓存Session/,二级缓存Namespaces)的进行了新增、修改、删除操作后，默认该作用域下所有 select 中的缓存将被clear</li><li>2,二级缓存需要缓存的数据实现 Serializable 接口</li><li>3,只有会话提交或者关闭以后，一级缓存中的数据才会转移到二级缓存中</li></ul><p>面试题：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202402291146216.png" alt="image.png"></p><ul><li><p>缓存</p><ul><li>一级缓存（本地缓存） <ul><li>一级缓存是 SqlSession 级别的，也就是说，只有在同一个 SqlSession 中的操作才能共享这个缓存。默认情况下，一级缓存是开启的</li></ul></li><li>二级缓存（全局缓存） <ul><li>二级缓存是跨 SqlSession 的，它是基于 namespace 级别的，即同一个 namespace 的不同 SqlSession 可以共享该缓存</li><li>需要显式开启。可以在 MyBatis 配置文件中全局开启，也可以在 mapper 映射文件中单独配置使用二级缓存</li><li>当一个 SqlSession 查询完数据并提交或关闭时，数据会从一级缓存转移到二级缓存中。当另一个 SqlSession 执行查询时，会先查看二级缓存，如果缓存中有数据，则直接使用缓存数据；如果没有，才会访问数据库，并将查询结果放入二级缓存</li></ul></li></ul></li></ul>`,133)])])}const b=a(p,[["render",o]]);export{h as __pageData,b as default};
